let max_roof_height = 80;

let col_pals = [['#c66655','#8e4843','#f2e4d4'],['#efe5d3','#edc8b1','#997f7a'],
							  ['#b1715b','#875645','#c69179'],['#879896','#6a7372','#ecdece'],['#ccb5a1','#baa094','#917970']];

function setup() {
	createCanvas(windowWidth, windowHeight);
	background('#f2e4d2');
	stroke(0);

	rows = 24;
	cols = 28;
	let scale = 0.4;
  //scale=0.7;
	for(row = 0; row < rows; row++)
	{
		for(col = 0; col < cols; col++)
		{
			let y = (displayHeight/rows)*row+random(-50,50);
			let x = (displayWidth/cols)*col+random(-50,50);
			let width = random(150,200)*scale;
			let height = random(400,500);
			let col_pal = col_pals[parseInt(random(0,col_pals.length))];

			drawBuilding(x,y,width,height,col_pal[0],col_pal[1],col_pal[2]);
		}
		scale+=0.02;
	}
}

function penline(p1,p2,w) {
	noStroke();
	fill(0);
	x = p1.x;
	y = p1.y;
	d = dist(p1.x, p1.y, p2.x, p2.y);
	spacing = 2;
	steps = d/spacing;
	dx = (p2.x - p1.x)/steps;
	dy = (p2.y - p1.y)/steps;

	for(n = 0; n < steps-1; n++)
	{	
		x += dx;
		y += dy;
		wr = random(0,1)-1+w;
		vr = parseInt(random(0,10));
		if(vr)
			circle(x,y,wr);
	}
}

function drawRect(p1,width,height,w) {
	let p2 = createVector(p1.x+width,p1.y);
	let p3 = createVector(p1.x+width,p1.y+height);
	let p4 = createVector(p1.x,p1.y+height);
	fill(255);
	rect(p1.x,p1.y,width,height);
	penline(p1,p2,w);
	penline(p2,p3,w);	
	penline(p3,p4,w);	
	penline(p1,p4,w);		
}

function drawTriangle(p1,p2,p3,fill){
	w = 5;
	penline(p1,p2,w);
	penline(p2,p3,w);
	penline(p3,p1,w)
}

function hatch(p1,p2,p3,p4,w,col) {
	// p1 - p2
	//  \    \
	//   p4 - p3

	let dx = p4.x-p1.x;
	let dy = p4.y-p1.y;
	var width = p2.x-p1.x;
	let step_size = random(5,15);
	let steps = parseInt(dy / step_size);
	for(let n = 1; n < steps; n++) {

		var x = p1.x + n*(dx/steps);
		var y = p1.y + n*(dy/steps);
		let xm =  p2.x+n*(dx/steps);
		if(parseInt(random(0,5)))
		{
			let part_length = 10;
			let parts = parseInt(width/part_length);
			for(let p = 1; p<parts-1; p++)
			{
				if(!parseInt(random(0,3)))
				{
					let pS = createVector(x+part_length*p,y);
					let pE = createVector(x+part_length*(p+1),y);
					penline(pS,pE,w);
				}
			}
		}
	}
}

function drawWindows(p, b_width, b_height, ink_width) {
	let border= 10;
	let w_gap = 30;
	let h_gap = 40;
	let w_width = 5+random(0,5);
	let w_height = 10+random(0,5);
	let rows = parseInt((b_height-border*2)/h_gap);
	let cols = parseInt((b_width-border*2)/w_gap);

	for(let n = 0; n <= rows; n++)
	{
		for(let m = 0; m <= cols; m++)
		{
			var x = p.x+border+w_gap*m;
			var y = p.y+border+h_gap*n;
			let pp = createVector(x,y);
			if(random(0,2)>1 && x+w_width < p.x+b_width)
				drawRect(pp,w_width,w_height,ink_width);
		}
	}
}


function drawBuildingPitchedFront(x,y,w,h, wallA_col, wallB_col, roof_col) {

	let ink_width = 3;

	let roof_height = min(h/2,max_roof_height)*random(0.2,1);
	let front_width = min(w,roof_height)*random(0.8,1.2);

	let side_width = w-front_width;
	let front_height = h-roof_height;

	let p1 = createVector(x+front_width/2,y);
	var p2 = createVector(x,y+roof_height);
	var p3 = createVector(x+front_width,y+roof_height);
	let p6 = createVector(x,y+roof_height+front_height);
	let p7 = createVector(x+front_width,y+roof_height+front_height);
  var p4 = createVector(x+front_width/2+side_width,y);
	let p5 = createVector(x+front_width+side_width,y+roof_height);
	let p8 = createVector(x+front_width+side_width,y+roof_height+front_height);

	// draw front wall
	fill(wallA_col);
	triangle(p1.x,p1.y,p2.x,p2.y,p3.x,p3.y);
	rect(p2.x,p2.y,front_width,front_height);
	hatch(p2,p3,p5,p6,ink_width-1);

	// draw roof
	fill(roof_col);
	quad(p1.x,p1.y, p4.x,p4.y, p5.x,p5.y, p3.x,p3.y)
	hatch(p1,p4,p5,p3,ink_width);

	// draw side wall
	fill(140);	
	fill(wallB_col);
	rect(p3.x,p3.y,side_width,front_height);
	hatch(p3,p4,p5,p6,ink_width-1);

	// draw outlines
	penline(p1,p2,ink_width);
	penline(p3,p1,ink_width);
	penline(p1,p4,ink_width);
	penline(p4,p5,ink_width);
	penline(p2,p6,ink_width);
	penline(p3,p7,ink_width);
	penline(p5,p8,ink_width);
	penline(p3,p5,ink_width);

	drawWindows(p2, front_width, front_height, ink_width);
	drawWindows(p3, side_width, front_height, ink_width);
}


function drawBuildingPitchedSide(x,y,w,h, wallA_col, wallB_col, roof_col) {

	var ink_width = 3;

	var roof_height = min(h/2,max_roof_height)*random(0.2,1);
	var front_width = w*0.2*random(0.8,1);

	var side_width = w-front_width;
	var front_height = h-roof_height;

	var p1 = createVector(x+front_width/2,y);
	var p2 = createVector(x,y+roof_height);
	var p3 = createVector(x+front_width,y+roof_height);
	var p6 = createVector(x,y+roof_height+front_height);
	var p7 = createVector(x+front_width,y+roof_height+front_height);
	var p4 = createVector(x+front_width/2-side_width,y);
  var p5 = createVector(x-side_width,y+roof_height);
  var p8 = createVector(x-side_width,y+roof_height+front_height);		

	// draw front wall
	fill(wallB_col);
	triangle(p1.x,p1.y,p2.x,p2.y,p3.x,p3.y);
	rect(p2.x,p2.y,front_width,front_height);

	// draw roof
	fill(roof_col);
	quad(p1.x,p1.y, p4.x,p4.y, p5.x,p5.y, p2.x,p2.y);
	hatch(p4,p1,p2,p5,ink_width);

	// draw side wall
	fill(wallA_col);
	rect(p2.x,p2.y,-side_width,front_height);		
	hatch(p5,p2,p6,p8,ink_width-1);

	// draw outlines
	penline(p1,p2,ink_width);
	penline(p3,p1,ink_width);
	penline(p1,p4,ink_width);
	penline(p4,p5,ink_width);
	penline(p2,p6,ink_width);
	penline(p3,p7,ink_width);
	penline(p5,p8,ink_width);
	penline(p2,p5,ink_width);

	//drawWindows(p2, front_width, front_height, ink_width);
	drawWindows(p5, side_width, front_height, ink_width);
}


function drawBuildingFlat(x,y,w,h, wallA_col, wallB_col, roof_col) {

	var ink_width = 3;

