  var p5 = createVector(x-side_width,y+roof_height);
  var p8 = createVector(x-side_width,y+roof_height+front_height);		

	let p10  = createVector(x+front_width-5,y+roof_height+10);
	let p9 = createVector(x-side_width+5,y+roof_height+10);

	// draw front wall
	fill(wallB_col);
	rect(p2.x,p2.y,front_width,front_height);

	// draw side wall
	fill(wallA_col);
	rect(p2.x,p2.y,-side_width,front_height);		
	hatch(p5,p2,p6,p8,ink_width-1);

	// draw outlines

	penline(p3,p5,ink_width);
	penline(p9,p10,ink_width);
	penline(p3,p5,ink_width);
