function drawBuilding(x,y,w,h, wallA_col, wallB_col, roof_col) {
	r = random(0,3);
	if(r > 1.0)
		drawBuildingPitchedFront(x,y,w,h, wallA_col, wallB_col, roof_col);
	else if(r > 0.3)
		drawBuildingPitchedSide(x,y,w,h, wallA_col, wallB_col, roof_col);
	else
		drawBuildingFlat(x,y,w,h, wallA_col, wallB_col, roof_col);

}

